import{_ as n,a0 as l,w as p,s,I as o,x as t,a1 as a,A as i,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"Calibre 1.6 正式發佈：更方便的標記圖書功能 | LCTT x X-CMD","titleTemplate":false,"description":"Calibre 1.6 正式發佈：更方便的標記圖書功能 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Calibre 1.6 正式發佈：更方便的標記圖書功能 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Calibre 1.6 正式發佈：更方便的標記圖書功能 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Calibre 1.6 released with handy mark-book feature","title":"Calibre 1.6 正式發佈：更方便的標記圖書功能","tag":"201310","desc":""},"relativePath":"201310/Calibre 1.6 released with handy mark-book feature.md","filePath":"[post].md"}'),b={name:"201310/Calibre 1.6 released with handy mark-book feature.md"};function d(m,e,g,C,f,k){const r=l("Link");return p(),s("div",null,[e[13]||(e[13]=o("h1",{id:"calibre-1-6-正式發佈-更方便的標記圖書功能",tabindex:"-1"},[t("Calibre 1.6 正式發佈：更方便的標記圖書功能 "),o("a",{class:"header-anchor",href:"#calibre-1-6-正式發佈-更方便的標記圖書功能","aria-label":"Permalink to “Calibre 1.6 正式發佈：更方便的標記圖書功能”"},"​")],-1)),o("p",null,[a(r,{href:"http://calibre-ebook.com/"},{default:i(()=>[...e[0]||(e[0]=[t("Calibre",-1)])]),_:1}),e[1]||(e[1]=t("是一個免費的開源電子圖書館管理工具，令人心動的設計思想，綜合了電子書相關範疇的要求和需求，提供了強大的轉換處理，專注於電子書的閲讀，輕而易舉的創建和管理書庫，集成在線服務等，總而言之，給你真真正正的現代化電子書閲讀體驗。",-1))]),e[14]||(e[14]=u(`<p>Calibre 已經更新到<strong>1.6</strong>版本，已有的<strong>標記圖書</strong>（book-marking）功能，做了大量的修補和功能增強。</p><p><strong>標記圖書</strong>作為一種<strong>暫定</strong>選書的簡便方式（重啓Calibre後就會失去標記），允許用户標記某本圖書，再點擊已標記的圖書便取消該標記，該特性能在很多場景提供便利。</p><p>最新實現的標記圖書功能並沒有默認開啓，當然，開啓它也是很容易的。<code>首選項(Prefences)--&gt;工具欄(Toolbar)--&gt;主工具欄(The main toolbar)--&gt;點擊標記圖書(Mark Books)--&gt;點擊左端的箭頭--&gt;應用(Apply)</code>，之後在工具欄上就有圖書標記按鈕。</p><p>舉個例子，<strong>標記</strong>你選擇的三本書（按住Ctrl鍵，並點擊選定的三本圖書），也可以通過工具欄上的按鈕，標記圖書。</p><p>最新標記的三本書將顯示一個特殊標記的圖標，這樣用户可以清楚的找到標記的書本。</p><p><img src="http://iloveubuntu.net/pictures_me/calibre%2016%20marking%20books.png" alt=""></p><p>在標記圖書後，用户可以通過&#39;右擊標記按鈕--&gt;顯示標記書本&#39;來只顯示已標記的圖書，同時隱藏未標記的圖書。</p><p>在有些時候想清楚觀察重點圖書，圖書標記功能允許用户輕而易舉的分離出偏愛的圖書，只需要花幾秒鐘點擊標記按鈕，即可清楚的展示某本書。</p><p>再次選擇標記圖書或再點擊標記圖書按鈕，將取消標記，按鈕在標記/不標記之間切換。</p><p>Calibre默認攜帶了好用的電子書閲讀器，在1.6版本增加了額外的快捷鍵配置，意味着現在用户能通過自己的喜好制定不同的<strong>快捷鍵</strong>例如放大縮小。</p><p>打開電子書閲讀器之前先調整快捷鍵，點擊工具條的首選項來設置快捷鍵，雙擊一個條目進行編輯。</p><p><img src="http://iloveubuntu.net/pictures_me/calibre%20font%20size%20shortcut.png" alt=""></p><p>以上提及的特性，連同大量的bug的修補、增加了最新的新聞源（一些的烏拉圭的新聞）和改進了一些新聞源（國家地理雜誌，紐約書評，聚焦，Carta Capital，Ming Pao，Neu Osnabrucker Zeitung），去感受更強大的Calibre吧!</p><p>###我們怎麼<strong>安裝</strong>Calibre 1.6呢?</p><p>複製以下命令到終端</p><pre><code>sudo python -c &quot;import sys; py3 = sys.version_info[0] &gt; 2; u = __import__(&#39;urllib.request&#39; if py3 else &#39;urllib&#39;, fromlist=1); exec(u.urlopen(&#39;http://status.calibre-ebook.com/linux_installer&#39;).read()); main()&quot;
</code></pre><p>按回車鍵，出現<code>Enter the installation directory for calibre [/opt]</code>再按回車鍵</p><p>如果用户通過PPA安裝了Calibre，那麼請先執行下列命令（在執行以上命令之前）。</p><pre><code>sudo apt-get remove calibre calibre-bin
</code></pre><hr>`,20)),o("p",null,[e[3]||(e[3]=t("via: ",-1)),a(r,{href:"http://iloveubuntu.net/calibre-16-released-handy-mark-book-feature"},{default:i(()=>[...e[2]||(e[2]=[t("http://iloveubuntu.net/calibre-16-released-handy-mark-book-feature",-1)])]),_:1})]),o("p",null,[e[6]||(e[6]=t("譯者：",-1)),a(r,{href:"https://github.com/Luoxcat"},{default:i(()=>[...e[4]||(e[4]=[t("Luoxcat",-1)])]),_:1}),e[7]||(e[7]=t(" 校對：",-1)),a(r,{href:"https://github.com/jasminepeng"},{default:i(()=>[...e[5]||(e[5]=[t("jasminepeng",-1)])]),_:1})]),o("p",null,[e[10]||(e[10]=t("本文由 ",-1)),a(r,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原創翻譯，",-1)),a(r,{href:"http://linux.cn/"},{default:i(()=>[...e[9]||(e[9]=[t("Linux中國",-1)])]),_:1}),e[12]||(e[12]=t(" 榮譽推出",-1))])])}const h=n(b,[["render",d]]);export{_ as __pageData,h as default};
